  CW += c[23] * 5.8036000000000001e+01; // CHOCHO
  CW += c[24] * 5.9043999999999997e+01; // C2H3OO
  CW += c[25] * 4.2036999999999999e+01; // CHCHO
  CW += c[26] * 2.6037999999999997e+01; // C2H2
  CW += c[27] * 4.5061000000000000e+01; // PC2H4OH
  CW += c[28] * 7.7058999999999997e+01; // O2C2H4OH
  CW += c[29] * 4.3045000000000002e+01; // CH2CHO
  CW += c[30] * 4.2036999999999999e+01; // CH2CO
  CW += c[31] * 4.1028999999999996e+01; // HCCO
  CW += c[32] * 4.4097000000000001e+01; // C3H8
  CW += c[33] * 4.3088999999999999e+01; // IC3H7
