  CW += c[36] * 5.7072000000000003e+01; // CH3CHCHO
  CW += c[37] * 7.4079000000000008e+01; // AC3H5OOH
  CW += c[38] * 4.0064999999999998e+01; // C3H4-P
  CW += c[39] * 4.0064999999999998e+01; // C3H4-A
  CW += c[40] * 3.9057000000000002e+01; // C3H3
  CW += c[41] * 3.8048999999999999e+01; // C3H2
  CW += c[42] * 5.6064000000000000e+01; // C2H3CHO
  CW += c[43] * 1.0020500000000000e+02; // NC7H16
  CW += c[44] * 1.3119499999999999e+02; // C7H15O2
  CW += c[45] * 1.4618599999999998e+02; // C7KET
  CW += c[46] * 9.9152999999999992e+01; // C5H11CO
  CW += c[47] * 1.1423200000000000e+02; // IC8H18
  CW += c[48] * 1.4522199999999998e+02; // C8H17O2
  CW += c[49] * 1.6021299999999999e+02; // C8KET
  CW += c[50] * 1.1317999999999999e+02; // C6H13CO
  CW += c[51] * 1.1221599999999999e+02; // C8H16
  CW += c[52] * 7.8114000000000004e+01; // C6H6
  // Now compute conversion
  amrex::Real CWinv = 1.0 / CW;
  y[0] = c[0] * 2.8013999999999999e+01 * CWinv;
  y[1] = c[1] * 2.0160000000000000e+00 * CWinv;
  y[2] = c[2] * 1.0080000000000000e+00 * CWinv;
  y[3] = c[3] * 3.1998000000000001e+01 * CWinv;
  y[4] = c[4] * 1.5999000000000001e+01 * CWinv;
