  y[36] = c[36] * 5.7072000000000003e+01 * CWinv;
  y[37] = c[37] * 7.4079000000000008e+01 * CWinv;
  y[38] = c[38] * 4.0064999999999998e+01 * CWinv;
  y[39] = c[39] * 4.0064999999999998e+01 * CWinv;
  y[40] = c[40] * 3.9057000000000002e+01 * CWinv;
  y[41] = c[41] * 3.8048999999999999e+01 * CWinv;
  y[42] = c[42] * 5.6064000000000000e+01 * CWinv;
  y[43] = c[43] * 1.0020500000000000e+02 * CWinv;
  y[44] = c[44] * 1.3119499999999999e+02 * CWinv;
  y[45] = c[45] * 1.4618599999999998e+02 * CWinv;
  y[46] = c[46] * 9.9152999999999992e+01 * CWinv;
  y[47] = c[47] * 1.1423200000000000e+02 * CWinv;
