  redP = Corr / k_f * 17370000 * exp(-1.23 * logT);
  F = redP / (1.0 + redP);
  logPred = log10(redP);
  logFcent = log10(
    (0.33) * exp(-T * 1e+30) + 0.67 * exp(-T * 1e-30) + exp(-1e+30 * invT));
  troe_c = -0.4 - 0.67 * logFcent;
  troe_n = 0.75 - 1.27 * logFcent;
