  F_troe = exp(M_LN10 * logFcent / (1.0 + troe * troe));
  Corr = F * F_troe;
  qf[2] *= Corr * k_f;
  qr[2] *= Corr * k_f * exp(-(g_RT[2] + g_RT[3] - g_RT[8])) * (refC);
  // reaction 3:  CH3 + H (+M) <=> CH4 (+M)
  k_f = 64700000 * exp((0.185) * logT - (-27.1736999534549) * invT);
